// Normalise the incoming message, drop duplicates (WhatsApp can redeliver), start a turn.
const m = $("When Called").first().json;
const seen = $input.all().map(i => i.json).some(r => r && r.message_id);
if (seen) return [];
const settings = Object.fromEntries($("Read Settings").all().map(i => [i.json.key, i.json.value ?? ""]));
const now = DateTime.now().setZone("Africa/Lagos");
const type = String(m.type ?? "text");
let text = String(m.text ?? "").trim();
if (type === "location" && m.location) {
  const l = m.location;
  text = "[Shared a location pin: " + [l.name, l.address].filter(Boolean).join(", ") + " (" + l.latitude + ", " + l.longitude + ")] " + text;
}
if (type === "image") text = "[Sent a photo" + (text ? " with caption: " + text : "") + ". You can't see photos; ask them to describe what they want.]";
if (!["text", "interactive", "audio", "location", "image"].includes(type)) text = "[Sent a " + type + " message, which this assistant can't read.]";
return [{
  json: {
    phone: String(m.phone ?? "").replace(/\D/g, ""),
    name: String(m.name ?? "").trim(),
    message_id: String(m.message_id ?? ""),
    type,
    media_id: String(m.media_id ?? ""),
    text: text.slice(0, 2000),
    test: m.test === true || String(m.test) === "true",
    turn_id: "t-" + now.toFormat("yyMMddHHmmss") + "-" + Math.random().toString(36).slice(2, 6),
    now: now.toISO(),
    settings,
  },
}];

// Is a person handling this chat right now (request_human)? Then the bot stays quiet.
const t = $("Prepare Turn").first().json;
const cust = $input.all().map(i => i.json).find(r => r && r.phone) || {};
const until = cust.handoff_until ? DateTime.fromISO(cust.handoff_until) : null;
const paused = Boolean(until && until.isValid && until > DateTime.now());
return [{ json: { ...t, paused, customer: { name: cust.name || "", orders_count: Number(cust.orders_count) || 0, handoff_until: cust.handoff_until || "" } } }];

const t = $("Check Pause").first().json;
const esc = s => String(s ?? "").replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");
return [{ json: { chat_id: t.settings.owner_chat_id, text: "💬 <b>" + esc(t.name || "Customer") + "</b> (+" + esc(t.phone) + "), bot paused:\n" + esc(t.text) } }];

// WhatsApp media URLs have no file extension; Whisper needs one to accept the upload.
const item = $input.first();
if (!item.binary || !item.binary.data) throw new Error("Voice note download returned no file");
item.binary.data.fileName = "voice-note.ogg";
item.binary.data.fileExtension = "ogg";
item.binary.data.mimeType = "audio/ogg";
return [item];

// ---- lib-shop.js (included by build.py): prices, carts, zones and delivery rules ----
const SHOP = {
  TZ: "Africa/Lagos",
  OPEN_DAYS: [1, 2, 3, 4, 5, 6], // Monday-Saturday
  CLOSED: ["2026-12-25", "2026-12-26", "2027-01-01"],
  // window label -> start hour
  WINDOWS: {
    delivery: { "10am-1pm": 10, "1pm-4pm": 13, "4pm-6pm": 16 },
    pickup: { "9am-12pm": 9, "12pm-3pm": 12, "3pm-7pm": 15 },
  },
  DAYS_AHEAD: 21,
  MAX_QTY: 50,
  CAKE_MESSAGE_MAX: 30,
  PICKUP: "14 Admiralty Way, Lekki Phase 1, Lagos",
};

const naira = n => "₦" + String(Math.round(Number(n) || 0)).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
const clean = s => String(s ?? "").toLowerCase().replace(/[^a-z0-9 ]+/g, " ").replace(/\s+/g, " ").trim();
const parseItems = json => {
  try { const a = JSON.parse(json || "[]"); return Array.isArray(a) ? a : []; } catch (e) { return []; }
};
const subtotalOf = items => items.reduce((s, i) => s + i.qty * i.unit_ngn, 0);
const itemLine = i => i.qty + " × " + i.name + (i.cake_message ? ' (message: "' + i.cake_message + '")' : "") + " = " + naira(i.qty * i.unit_ngn);
const newId = prefix => prefix + Array.from({ length: 4 }, () => "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"[Math.floor(Math.random() * 32)]).join("");

// Product by SKU, else by name words (all words of the query must appear).
function findProduct(products, ref) {
  const r = String(ref ?? "").trim();
  if (!r) return null;
  const bySku = products.find(p => p.sku.toLowerCase() === r.toLowerCase());
  if (bySku) return bySku;
  const words = clean(r).split(" ").filter(w => w.length > 1);
  const hits = products.filter(p => words.every(w => clean(p.name + " " + p.sku).includes(w)));
  return hits.length === 1 ? hits[0] : null;
}

// Delivery zone whose name or alias appears in the customer's text.
function matchZone(zones, text) {
  const t = " " + clean(text) + " ";
  let best = null;
  for (const z of zones) {
    const names = [z.area, ...String(z.aliases ?? "").split(",")].map(clean).filter(Boolean);
    for (const n of names) {
      if (t.includes(" " + n + " ") && (!best || n.length > best.len)) best = { zone: z, len: n.length };
    }
  }
  return best ? best.zone : null;
}

function isOpenDay(d) {
  return SHOP.OPEN_DAYS.includes(d.weekday) && !SHOP.CLOSED.includes(d.toISODate());
}

// Earliest (day, window) that respects the longest lead time in the cart.
function earliestSlot(leadHours, fulfilment, now) {
  const windows = SHOP.WINDOWS[fulfilment] || SHOP.WINDOWS.delivery;
  const ready = now.plus({ hours: leadHours });
  for (let d = now.startOf("day"); d <= now.startOf("day").plus({ days: SHOP.DAYS_AHEAD }); d = d.plus({ days: 1 })) {
    if (!isOpenDay(d)) continue;
    for (const [label, hour] of Object.entries(windows)) {
      if (d.set({ hour }) >= ready) return { date: d, window: label };
    }
  }
  return null;
}

// "Thursday 30 October, 1pm-4pm"
const sayDay = d => d.toFormat("cccc d LLLL");
// ---- end lib-shop.js ----
// Everything the agent needs this turn in one prompt: who, when, cart, recent orders, the last
// 12 messages, and the new message (transcribed if it was a voice note).
const t = $("Check Pause").first().json;
let text = t.text;
let voice = false;
if ($("Transcribe Voice Note").isExecuted) {
  const tr = $("Transcribe Voice Note").first().json;
  text = String(tr.text ?? "").trim();
  voice = true;
}
const history = $("Read History").all().map(i => i.json).filter(r => r && r.text).reverse();
const orders = $("Read Orders").all().map(i => i.json).filter(o => o && o.order_id);
const now = DateTime.now().setZone(SHOP.TZ);
const cart = orders.find(o => o.status === "cart" && parseItems(o.items_json).length) || orders.find(o => o.status === "awaiting_payment");
const paidCount = orders.filter(o => ["paid", "baking", "out_for_delivery", "ready_for_pickup", "delivered"].includes(o.status)).length;
const placed = orders.filter(o => !["cart"].includes(o.status)).slice(0, 3);
const slot = (hours, how) => { const s = earliestSlot(hours, how, now); return s ? sayDay(s.date) + " " + s.window : "none in 3 weeks"; };
const lines = [
  "Customer: " + (t.name || "unknown name") + " (WhatsApp +" + t.phone + ")" + (paidCount ? ", returning customer with " + paidCount + " paid order(s)" : ""),
  "Now: " + now.toFormat("cccc d LLLL yyyy, h:mm a") + " in Lagos",
  "Earliest possible right now, delivery / pickup: same-day items " + slot(3, "delivery") + " / " + slot(3, "pickup") +
    "; small chops tray (24h) " + slot(24, "delivery") + " / " + slot(24, "pickup") +
    "; celebration cakes (48h) " + slot(48, "delivery") + " / " + slot(48, "pickup"),
  "Open cart: " + (cart ? cart.order_id + " (" + cart.status + "): " + parseItems(cart.items_json).map(itemLine).join("; ") : "none"),
  "Recent orders: " + (placed.length ? placed.map(o => o.order_id + " " + o.status + " " + naira(o.total_ngn) + " for " + o.deliver_on + " " + o.window).join("; ") : "none"),
  "",
  "Conversation so far (oldest first):",
  ...(history.length ? history.map(h => (h.role === "user" ? "Customer: " : "Honey: ") + String(h.text).slice(0, 600)) : ["(new conversation)"]),
  "",
  "New message from the customer" + (voice ? " (voice note, transcribed)" : "") + ":",
  text || "(empty message)",
];
return [{ json: { ...t, text, voice, prompt: lines.join("\n") } }];

